const input = $('Local Task Webhook').first().json.body;
const result = $json;
if (!input?.task_id || !input?.trace_id || !input?.role_id) throw new Error('Missing correlation fields');
if (result.model !== input.model || !result.message || typeof result.message.content !== 'string' || !result.message.content.trim()) throw new Error('Invalid local model response');
return { json: { task_id: input.task_id, trace_id: input.trace_id, role_id: input.role_id, status: 'completed', output: result.message.content, provider: 'ollama-local', model: result.model, measured_runtime_ns: result.total_duration ?? null, prompt_tokens: result.prompt_eval_count ?? null, output_tokens: result.eval_count ?? null, execution_id: $execution.id } };
